                radial-gradient(circle at 20% 30%, rgba(99, 102, 241, 0.08) 0%, transparent 20%),
                radial-gradient(circle at 80% 70%, rgba(139, 92, 246, 0.08) 0%, transparent 20%);
            pointer-events: none;
            z-index: -1;
        }

        .container {
            max-width: 1200px;
            margin: 0 auto;
            padding: 0 2rem;
            height: 100vh;
            display: flex;
